INSERT INTO `v1_a153403c51941fb316d983693cfb4e95ad4b7f1e85e739b5efd058c601bf4bd1` VALUES (10011, "【加速】4以上：\n重複可能の行動速度アップ（【加速】数×5％）\n", 4, 1);
